{
  "findings": [
    {
      "check_id": "CKV_GCP_121",
      "title": "Cloud SQL instance does not have deletion protection enabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'deletion_protection' attribute is explicitly set to false, which allows the database instance to be accidentally or maliciously deleted without safeguards, risking data loss for the financial trading platform."
    }
  ],
  "patched_code": "resource "google_sql_database_instance" "trading_database" {
  name             = "real-time-financial-trading-platform-database-trading"
  database_version = "POSTGRES_13"
  region           = var.region
  deletion_protection = true
  settings {
    tier = "db-n1-standard-2"
    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.trading_platform_vpc.id
    }
    database_flags {
      name  = "log_connections"
      value = "off"
    }
    backup_configuration {
      enabled                        = true
      start_time                     = "03:00"
      point_in_time_recovery_enabled = true
    }
  }
  depends_on = [google_service_networking_connection.private_vpc_connection]
}",
  "fix_summary": "Enabled deletion protection by setting 'deletion_protection' to true on the Cloud SQL instance to prevent accidental or unauthorized deletion."
}
